window.RP_SESSION={"id":"S-04222a629033","messages":[{"id":"RP-II-0104205","time":"2026-06-02T09:15:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"언젠간 너를 찾아낼 거야, 어디서든 너를 찾아내고 말거야.\n\n무슨 방법이 필요하든.\n\n너를 어떻게든···.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0104206","time":"2026-06-02T09:16:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"집착 가득 담긴, 증오와 애정을 통해 흘러나오는 유연한 노래소리. 길드의 깊은 산 속에서는 아마 류트 소리가 들려올 겁니다.\n\n띵, 띵···. 가볍게 울려퍼지는 류트는 어느새 감정을 노래하는 것을 멈추고.\n\n강아지 가면을 쓴 존재는 큼, 목을 가다듬습니다.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0104207","time":"2026-06-02T09:17:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"제대로 된 연주를 보여주마!","characters":["P-051c3e67e69c"]},{"id":"RP-II-0104208","time":"2026-06-02T09:17:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"https://youtu.be/RZ4H0KJezNE?si=TpcOIISkM09ZbrP8","characters":["P-051c3e67e69c"]},{"id":"RP-II-0104209","time":"2026-06-02T09:19:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"현란하게 울려퍼지는 류트 소리, 베스퍼의 손이 섬세하게 류트를 다듬고 줄을 튕겨냅니다. 띵, 딩, 딩 디딩, 딩. \n\n이것은 번개와도 같은 울려퍼짐이다!","characters":["P-051c3e67e69c"]},{"id":"RP-II-0104210","time":"2026-06-02T09:21:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"이런 짜릿한 곡의 이름은 내리쳐진 벼락! 그리고 그것을 부르는 무리의 이름은..\n\n······ 베스퍼가 시장 아줌마에게 가장 많이 하는 문장으로!","characters":["P-051c3e67e69c"]},{"id":"RP-II-0104211","time":"2026-06-02T09:22:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"‘ 에이씨, D.C 좀 해줘! ‘","characters":["P-051c3e67e69c"]},{"id":"RP-II-0104212","time":"2026-06-02T09:22:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"좋습니다. 이 무리의 이름은\n\n에이씨디씨!\n\n깎아주지 않은 아줌마를 향한 천벌을 기도하는 강렬한 노래입니다.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0104213","time":"2026-06-02T09:22:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-051c3e67e69c"]},{"id":"RP-II-0104214","time":"2026-06-02T09:22:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]},{"id":"RP-II-0104215","time":"2026-06-02T09:26:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"https://youtu.be/tAVCISkazwM?si=4-7u7DAt1ShgFCBe","characters":["P-051c3e67e69c"]}]};
